//! Lighting environment of the project.

use serde::{Deserialize, Serialize};

use crate::resource::ResourceHash;

/// Where the environment image comes from.
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum EnvironmentSource {
    /// Procedural studio sky generated by the application.
    #[default]
    Studio,
    /// HDRI shipped with the application, by file name (`assets/environments`).
    Bundled(String),
    /// HDRI imported by the user, stored in the project.
    Resource(ResourceHash),
}

/// Environment lighting the viewport.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct EnvironmentSettings {
    /// Image.
    pub source: EnvironmentSource,
    /// Rotation around the vertical axis, radians in `[0, 2π)`.
    pub rotation: f32,
    /// Exposure in EV, applied before tone mapping.
    pub exposure_ev: f32,
}

impl Default for EnvironmentSettings {
    fn default() -> Self {
        Self {
            source: EnvironmentSource::Studio,
            rotation: 0.0,
            exposure_ev: 0.0,
        }
    }
}
